To solve the problem of finding the mode(s) in a binary search tree (BST) with duplicates, we can perform an in-order traversal of the tree to get the elements in sorted order. We will then count the frequency of each element and keep track of the maximum frequency and the elements that achieve this frequency.

Here's a C++ implementation:

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <limits>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

int findMode(TreeNode* root, int& max_count, int& current_count, int& prev_val, std::vector<int>& modes) {
    if (root == nullptr) return 0;

    // Traverse the left subtree
    findMode(root->left, max_count, current_count, prev_val, modes);

    // Update the current count
    if (prev_val == root->val) {
        current_count++;
    } else {
        current_count = 1;
    }

    // Update the maximum count if necessary
    if (current_count > max_count) {
        max_count = current_count;
        modes.clear(); // Clear previous modes
        modes.push_back(root->val);
    } else if (current_count == max_count) {
        modes.push_back(root->val);
    }

    // Update the previous value
    prev_val = root->val;

    // Traverse the right subtree
    findMode(root->right, max_count, current_count, prev_val, modes);

    return max_count;
}

std::vector<int> findModeBST(TreeNode* root) {
    std::vector<int> modes;
    int max_count = 0;
    int current_count = 0;
    int prev_val = std::numeric_limits<int>::min();

    findMode(root, max_count, current_count, prev_val, modes);

    return modes;
}

void printModes(const std::vector<int>& modes) {
    for (int mode : modes) {
        std::cout << mode << " ";
    }
    std::cout << std::endl;
}

int main() {
    // Constructing a simple BST for demonstration
    TreeNode* root = new TreeNode(1);
    root->right = new TreeNode(2);
    root->right->left = new TreeNode(2);

    std::vector<int> result = findModeBST(root);
    printModes(result

